// Types the package only declares: its JavaScript has no interfaces and no
// conditional aliases, so code typed from the JavaScript sees `any` here.
export interface TSchema {
  readonly kind: string;
  describe(): string;
}
export interface TNumber extends TSchema {
  readonly kind: "number";
}
export interface TString extends TSchema {
  readonly kind: "string";
}
export interface TArray<T extends TSchema = TSchema> extends TSchema {
  readonly kind: "array";
  readonly items: T;
}
export type Static<T extends TSchema> = T extends TNumber
  ? number
  : T extends TString
    ? string
    : T extends TArray<infer I>
      ? Static<I>[]
      : unknown;
export declare function Num(): TNumber;
export declare function Str(): TString;
export declare function Arr<T extends TSchema>(items: T): TArray<T>;
export declare function check<T extends TSchema>(schema: T, value: unknown): value is Static<T>;
